// seed: tests/seed.hunter_plus.spec.ts
// Read-only: never click «לרכישה» / «הפעלת הקידום». J-73 must stay active (KEEP data).
import { test, expect, Page } from '@playwright/test';
import path from 'path';

test.use({ storageState: path.join(__dirname, '../../../auth/hunter_plus.json') });

const JOB = 'QA-AUTO 1020 C2 verify שכר נמוך';
const THRESHOLD = 'זמין למשרות עם שכר של ₪20,000 ומעלה';

async function openUpgrade(page: Page, title: string) {
  const card = page.getByRole('listitem').filter({ has: page.getByRole('heading', { name: title, exact: true }) });
  await expect(card).toHaveCount(1);
  const upgrade = page.getByRole('menuitem', { name: 'שדרוג משרה' });
  await expect(async () => {
    if (!(await upgrade.isVisible())) await card.getByRole('button', { name: 'פעולות משרה' }).click();
    await expect(upgrade).toBeVisible({ timeout: 2_000 });
  }).toPass({ timeout: 15_000 });
  await upgrade.click();
  const dialog = page.getByRole('dialog', { name: 'האם לשדרג את המשרה שלכם?' });
  await expect(dialog).toBeVisible();
  return dialog;
}

test.describe('Job upgrade popup — ₪20,000 threshold (#1396b6)', () => {
  test('Job below ₪20,000: promotion and distribution are disabled with the threshold text @desktop @prod-safe #1396b6', async ({ page }) => {
    // 1. «המשרות שלי» → J-73 → «•••» → «שדרוג משרה»
    await page.goto('/my-jobs');
    const dialog = await openUpgrade(page, JOB);

    // 2. Subtitle = job title
    await expect(dialog.getByText(JOB, { exact: true })).toBeVisible();

    const promo = dialog.getByRole('button', { name: /^קידום משרה/ });
    const dist = dialog.getByRole('button', { name: /^שירותי הפצה/ });
    for (const card of [promo, dist]) {
      await expect(card).toBeDisabled();
      await expect(card).toContainText(THRESHOLD);
      await expect(card).toContainText('(לפי תחילת טווח השכר)');
      await expect(card).toHaveAttribute('aria-pressed', 'false');
      await expect(card).toHaveCSS('opacity', '0.5'); // greyed
    }

    // 3. Try to select «קידום משרה» — stays not selected
    await promo.click({ force: true });
    await expect(promo).toHaveAttribute('aria-pressed', 'false');
    await expect(dist).toHaveAttribute('aria-pressed', 'false');

    // 4. «לא תודה» — popup closed, no payment window
    await dialog.getByRole('button', { name: 'לא תודה', exact: true }).click();
    await expect(dialog).toBeHidden();
    await expect(page.getByRole('dialog')).toHaveCount(0);
    await expect(page).toHaveURL(/\/my-jobs/);
  });
});
